import base64
import string
import numpy as np

def is_printable_ascii(b):
    # Treat tab/newline as printable, too, for plaintexts
    return chr(b) in string.printable or b in (9, 10, 13)

def xor_bytes(a, b):
    return bytes([x ^ y for x, y in zip(a, b)])

def probable_score(line):
    # Score: +2 alpha, +1 printables, -4 control/nonprintable
    s = 0
    for c in line:
        if c in string.ascii_letters: s += 2
        elif c in string.printable: s += 1
        else: s -= 4
    return s

def recover_key_space(ciphertexts):
    # c_i xor c_j = m_i xor m_j
    n = len(ciphertexts)
    mlens = [len(c) for c in ciphertexts]
    L = max(mlens)
    score_space = np.zeros((n, L), dtype=int)
    for i in range(n):
        for j in range(n):
            if i == j: continue
            xored = xor_bytes(ciphertexts[i], ciphertexts[j])
            for idx, b in enumerate(xored):
                # If the result is alpha (when xor'ing with space), 1 of orig. was likely a space
                if chr(b) in string.ascii_letters:
                    score_space[i, idx] += 1
                    score_space[j, idx] += 1
    return score_space

def guess_key(ciphertexts, space_scores, threshold=0.6):
    # For each position, if many pairwise xor give printable (far more than expected random)
    n = len(ciphertexts)
    L = space_scores.shape[1]
    key_guess = [None] * L
    for i in range(L):
        hit = 0
        who = -1
        for row in range(n):
            if space_scores[row, i] > (n-1)*threshold:
                hit += 1
                who = row
        if hit == 1:
            # Only one row, so assume that pos in that ct is space
            key_guess[i] = ciphertexts[who][i] ^ ord(' ')
    return key_guess

def decrypt_with_partial_key(ct, key_guess):
    result = []
    for i, c in enumerate(ct):
        if i < len(key_guess) and key_guess[i] is not None:
            p = c ^ key_guess[i]
            result.append(chr(p) if is_printable_ascii(p) else '_')
        else:
            result.append('_')
    return ''.join(result)

def main():
    with open("/home/ctfplayer/ctf_files/assignment.txt", "r") as f:
        lines = f.read().splitlines()
    cts = []
    for ln in lines:
        if ln and all(c in string.ascii_letters+string.digits+'+/=' for c in ln.strip()):
            try:
                cts.append(base64.b64decode(ln.strip()))
            except:
                continue
    ml = max(len(c) for c in cts)
    cts = [c.ljust(ml, b'\x00') for c in cts]  # pad to same len with NUL (will be blanks in output)
    space_score = recover_key_space(cts)
    key_guess = guess_key(cts, space_score, threshold=0.7)
    candidates = [decrypt_with_partial_key(ct, key_guess) for ct in cts]
    # Sort/high-score longest with highest ASCII content
    candidates = sorted(list(set(candidates)), key=lambda s: (s.count('_')*-2 + probable_score(s), -s.count('_'), -len(s)), reverse=True)
    with open("/home/ctfplayer/best_decrypts.txt", "w") as f:
        for ln in candidates[:3]:
            f.write(ln+"\n")
    # Print for logging:
    for ln in candidates[:3]:
        print(ln)

if __name__ == '__main__':
    main()

