from collections import Counter, defaultdict

CIPHERTEXT_FILE = '/home/ctfplayer/top_ciphertexts.txt'

# Score decoded text on likelihood of being English.
def score(text):
    # Favors valid ASCII and English letter frequency
    english_freq = {
        'E': 12.70, 'T': 9.06, 'A': 8.17, 'O': 7.51, 'I': 6.97, 'N': 6.75, 'S': 6.33, 'H': 6.09, 'R': 5.99,
        'D': 4.25, 'L': 4.03, 'C': 2.78, 'U': 2.76, 'M': 2.41, 'W': 2.36, 'F': 2.23, 'G': 2.02, 'Y': 1.97,
        'P': 1.93, 'B': 1.29, 'V': 0.98, 'K': 0.77, 'X': 0.15, 'J': 0.15, 'Q': 0.10, 'Z': 0.07
    }
    s = 0
    for c in text.upper():
        if c in string.ascii_uppercase:
            s += english_freq.get(c, 0)
        elif c in string.whitespace:
            s += 2.0
        elif c in string.printable:
            s += 0.2
        else:
            s -= 5
    return s

def xor_bytes(b1, b2):
    return bytes([a ^ b for a, b in zip(b1, b2)])

def get_space_likely_positions(pairs):
    likely = defaultdict(Counter)
    for i, c1 in enumerate(pairs):
        for j, c2 in enumerate(pairs):
            if i == j: continue
            r = xor_bytes(c1, c2)
            for pos, val in enumerate(r):
                # If result is in alphabetic ASCII, assume one text had space
                if 65 <= val <= 90 or 97 <= val <= 122:
                    likely[i][pos] += 1
    # Threshold: appeared as likely space in >70% of xor pairs
    min_pairs = int(len(pairs) * 0.7)
    spaces = [set() for _ in pairs]
    for i, c in likely.items():
        for pos, count in c.items():
            if count >= min_pairs:
                spaces[i].add(pos)
    return spaces

def recover_key(ciphertexts):
    maxlen = max(map(len, ciphertexts))
    key = [None] * maxlen
    spaces = get_space_likely_positions(ciphertexts)
    for i, ctext in enumerate(ciphertexts):
        for pos in spaces[i]:
            # If ctext[pos] = ciphertext byte, and was probably a space there
            keybyte = ctext[pos] ^ 0x20
            if key[pos] is None:
                key[pos] = keybyte
    return key

def decode_plaintexts(ciphertexts, key):
    results = []
    for ct in ciphertexts:
        pt = bytearray()
        for i in range(len(ct)):
            if i < len(key) and key[i] is not None:
                pt.append(ct[i] ^ key[i])
            else:
                pt.append(ord('_'))
        results.append(pt.decode(errors='replace'))
    return results

def main():
    cts = [base64.b64decode(line.strip()) for line in open(CIPHERTEXT_FILE) if line.strip()]
    key = recover_key(cts)
    pts = decode_plaintexts(cts, key)
