# Extract the base64 ciphertext blocks from the challenge file
def extract_ciphertexts(fname):
    cts = []
    cbuf = []
    inblock = False
    with open(fname, 'r') as f:
        for line in f:
            l = line.strip()
            if l:
                if all(c in string.ascii_letters+string.digits+'+/=' for c in l):
                    cbuf.append(l)
                elif cbuf:
                    cts.append(base64.b64decode(''.join(cbuf)))
                    cbuf = []
        if cbuf:
            cts.append(base64.b64decode(''.join(cbuf)))
    return cts

# Frequency score for English/text
f_table = {
    'E':12.02, 'T':9.10, 'A':8.12, 'O':7.68, 'I':7.31, 'N':6.95, 'S':6.28,
    'R':6.02, 'H':5.92, 'D':4.32, 'L':3.98, 'U':2.88, 'C':2.71, 'M':2.61,
    'F':2.30, 'Y':2.11, 'W':2.09, 'G':2.03, 'P':1.82, 'B':1.49, 'V':1.11,
    'K':0.69, 'X':0.17, 'Q':0.11, 'J':0.10, 'Z':0.07, ' ':10
}
def score_text(txt):
    s = 0
    for b in txt:
        c = chr(b)
        if c.upper() in f_table:
            s += f_table[c.upper()]
        elif 32 <= b < 127:
            s += 0.3 # printable
        else:
            s -= 2 # likely not text
    return s

def try_crack_key(ciphertexts, keylen):
    # List of arrays (bytearray)
    ctbytes = [bytearray(c) for c in ciphertexts]
    K = [None]*keylen
    # Guess locations of space in every position using many-time pad logic
    for pos in range(keylen):
        hits = Counter()
        for i, ct1 in enumerate(ctbytes):
            if pos >= len(ct1):
                continue
            is_space_in_some = 0
            for j, ct2 in enumerate(ctbytes):
                if i == j:
                    continue
                if pos < len(ct2):
                    c = ct1[pos] ^ ct2[pos]
                    # If XOR results in alpha (ignoring case), it's likely one is space
                    if 65 <= c <= 90 or 97 <= c <= 122:
                        is_space_in_some += 1
            if is_space_in_some >= (len(ctbytes)//2):
                # guess space in ct1
                k_guess = ct1[pos] ^ 0x20
                hits[k_guess] += 1
        if hits:
            # pick by most votes
            K[pos] = hits.most_common(1)[0][0]
    return K

def decrypt_all(ciphertexts, key):
    knowns = []
    for c in ciphertexts:
        pt = bytearray()
        for i in range(len(c)):
            if i < len(key) and key[i] is not None:
                pt.append(c[i]^key[i])
            else:
                pt.append(0x2e) # dot for unknown
        knowns.append(pt)
    return knowns

